-- 受領EXEから抽出した現行Oracle用SQL。新MCMでは直接使用しない。
-- 元処理: SupportCntGet / 抽出位置: IL_0023
SELECT MAR.MEISHO4_NK, UKB.SUPPORT_ID
FROM MCM_UK_KEIYAKU UKA
JOIN MCM_UK_KIKAN   UKB    ON UKB.UK_KEIYAKU_ID = UKA.UK_KEIYAKU_ID
JOIN MCM_UK_SEIBAN UKI    ON UKI.UK_KEIYAKU_ID = UKA.UK_KEIYAKU_ID
JOIN MCM_MA_TENPO MAR    ON MAR.TENPO_ID = UKB.IRAITENPO_ID
WHERE UKA.JOTAI = '2'   AND (          UKA.KAIYAKU_DT IS NULL    OR            TRUNC(UKA.KAIYAKU_DT) >= TRUNC(SYSDATE)       )   AND (         (           UKA.ENTYOKEIYAKUMANRYO_DT IS NULL   AND     (              UKA.KEIYAKUMANRYO_DT IS NULL    OR        TRUNC(UKA.KEIYAKUMANRYO_DT) >= TRUNC(SYSDATE)           )         )    OR   (           UKA.ENTYOKEIYAKUMANRYO_DT IS NOT NULL   AND     TRUNC(UKA.ENTYOKEIYAKUMANRYO_DT) >= TRUNC(SYSDATE)         )       )   AND UKI.UK_SEIBAN_ID = (                            SELECT MAX(UKZ.UK_SEIBAN_ID)
FROM MCM_UK_SEIBAN UKZ
WHERE UKZ.UK_KEIYAKU_ID = UKA.UK_KEIYAKU_ID                               AND TRUNC(UKZ.KAISI_DT)  <= TRUNC(SYSDATE)                               AND TRUNC(UKZ.SYURYO_DT) >= TRUNC(SYSDATE)                          )   AND UKB.UK_KIKAN_ID = (                           SELECT MAX(SS.UK_KIKAN_ID)
FROM MCM_UK_KIKAN SS
WHERE SS.UK_KEIYAKU_ID = UKA.UK_KEIYAKU_ID                              AND YUKO_FLG = 0                              AND TRUNC(SS.KAISI_DT)  <= TRUNC(SYSDATE)                              AND TRUNC(SS.SYURYO_DT) >= TRUNC(SYSDATE)                         )
GROUP BY MAR.MEISHO4_NK, UKB.SUPPORT_ID
ORDER BY MAR.MEISHO4_NK, UKB.SUPPORT_ID
